const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const chords=[
{id:'major',name:'大三和弦',suffix:'',formula:'1 · 3 · 5',intervals:[0,4,7],labels:['根音','大三度','纯五度'],group:'triad',text:'根音向上 4 个半音是大三度，再向上 3 个半音得到五音。大三和弦由此形成。'},
{id:'minor',name:'小三和弦',suffix:'m',formula:'1 · ♭3 · 5',intervals:[0,3,7],labels:['根音','小三度','纯五度'],group:'triad',text:'把大三和弦的三音降低一个半音，五音保持不变。结构从 4 + 3 变成了 3 + 4。'},
{id:'dim',name:'减三和弦',suffix:'dim',formula:'1 · ♭3 · ♭5',intervals:[0,3,6],labels:['根音','小三度','减五度'],group:'triad',text:'连续叠加两个小三度，根音到五音只有 6 个半音，形成减五度。'},
{id:'aug',name:'增三和弦',suffix:'aug',formula:'1 · 3 · ♯5',intervals:[0,4,8],labels:['根音','大三度','增五度'],group:'triad',text:'连续叠加两个大三度。大三和弦的五音升高一个半音，就成为增三和弦。'},
{id:'maj7',name:'大七和弦',suffix:'maj7',formula:'1 · 3 · 5 · 7',intervals:[0,4,7,11],labels:['根音','大三度','纯五度','大七度'],group:'seventh',text:'在大三和弦上加入距根音 11 个半音的大七度音。它与属七和弦的区别在七音。'},
{id:'m7',name:'小七和弦',suffix:'m7',formula:'1 · ♭3 · 5 · ♭7',intervals:[0,3,7,10],labels:['根音','小三度','纯五度','小七度'],group:'seventh',text:'小三和弦加上小七度。留意三音与七音，它们共同决定了和弦的色彩。'},
{id:'7',name:'属七和弦',suffix:'7',formula:'1 · 3 · 5 · ♭7',intervals:[0,4,7,10],labels:['根音','大三度','纯五度','小七度'],group:'seventh',text:'大三和弦加上小七度。三音与七音形成三全音；处于调内属功能时，常有向主和弦解决的倾向。'},
{id:'m7b5',name:'半减七和弦',suffix:'m7♭5',formula:'1 · ♭3 · ♭5 · ♭7',intervals:[0,3,6,10],labels:['根音','小三度','减五度','小七度'],group:'seventh',text:'减三和弦加小七度，也写作 ø7。它和减七和弦的七音不同。'},
{id:'dim7',name:'减七和弦',suffix:'dim7',formula:'1 · ♭3 · ♭5 · 𝄫7',intervals:[0,3,6,9],labels:['根音','小三度','减五度','减七度'],group:'seventh',text:'减三和弦上加入减七度，连续叠加三个小三度。减七度与大六度在十二平均律中等音，但拼写和功能不同。'},
{id:'sus2',name:'挂二和弦',suffix:'sus2',formula:'1 · 2 · 5',intervals:[0,2,7],labels:['根音','大二度','纯五度'],group:'sus',text:'用二音替代三音，保留根音与五音。缺少三音，因此不直接呈现大三或小三的色彩。'},
{id:'sus4',name:'挂四和弦',suffix:'sus4',formula:'1 · 4 · 5',intervals:[0,5,7],labels:['根音','纯四度','纯五度'],group:'sus',text:'用四音替代三音。可以试着从 sus4 切回大三，听见四音下降到三音的变化。'}];
const roots=[['C',0],['D♭',1],['D',2],['E♭',3],['E',4],['F',5],['F♯',6],['G',7],['A♭',8],['A',9],['B♭',10],['B',11]];
const letters=['C','D','E','F','G','A','B'],natural={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
function spell(root,interval,index,chord){const degrees=chord.degrees||(chord.group==='sus'?[0,chord.id==='sus2'?1:3,4]:[0,2,4,6]);const letter=letters[(letters.indexOf(root[0][0])+degrees[index])%7];let accidental=((root[1]+interval-natural[letter]+18)%12)-6;return letter+(accidental===-2?'𝄫':accidental===-1?'♭':accidental===1?'♯':accidental===2?'𝄪':'');}
let selected=chords[0],rootIndex=0,filter='all',ctx,progressionBusy=false;
$('#root').innerHTML=roots.map((r,i)=>`<option value="${i}">${r[0]}</option>`).join('');
$('#chordTypes').innerHTML=chords.filter(c=>['major','minor','dim','aug','maj7','m7','7','sus4'].includes(c.id)).map(c=>`<button data-chord="${c.id}">${c.name.replace('和弦','')}</button>`).join('');
const whiteMidi=[];for(let m=60;m<=84;m++)if([0,2,4,5,7,9,11].includes(m%12))whiteMidi.push(m);
$('#keyboard').innerHTML=whiteMidi.map(m=>`<button class="key white" data-midi="${m}" aria-label="${roots.find(r=>r[1]===m%12)[0]}${Math.floor(m/12)-1}">${roots.find(r=>r[1]===m%12)[0]}<small>${Math.floor(m/12)-1}</small></button>`).join('')+Array.from({length:25},(_,i)=>60+i).filter(m=>![0,2,4,5,7,9,11].includes(m%12)).map(m=>{const before=whiteMidi.filter(w=>w<m).length;return `<button class="key black" data-midi="${m}" style="left:calc(${before/15*100}% - 2.1%)" aria-label="${roots.find(r=>r[1]===m%12)[0]}${Math.floor(m/12)-1}">${roots.find(r=>r[1]===m%12)[0]}</button>`}).join('');
function currentNotes(){return selected.intervals.map(n=>60+roots[rootIndex][1]+n)}
function render(){const root=roots[rootIndex];$('#chordSymbol').textContent=root[0]+selected.suffix;$('#chordName').textContent=selected.name;$('#formula').innerHTML=selected.intervals.map((n,i)=>`${i?'<b>+</b>':''}<span class="tone">${spell(root,n,i,selected)}<small>${selected.labels[i]}</small></span>`).join('');$('#explainTitle').textContent=selected.formula+'，是它的构成方式';$('#explainText').textContent=selected.text;$$('[data-chord]').forEach(b=>{b.classList.toggle('active',b.dataset.chord===selected.id);b.setAttribute('aria-pressed',b.dataset.chord===selected.id)});const notes=currentNotes();$$('.key').forEach(k=>{const m=+k.dataset.midi;k.classList.toggle('selected',notes.includes(m));k.classList.toggle('root',m===notes[0]);});}
function audio(){if(!ctx)ctx=new (window.AudioContext||window.webkitAudioContext)();return ctx.resume().then(()=>ctx)}
async function sound(notes,spacing=0,duration=1.6){try{await audio();const start=ctx.currentTime+.025;notes.forEach((m,i)=>{const t=start+i*spacing;const gain=ctx.createGain();gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.13/Math.sqrt(notes.length),t+.015);gain.gain.exponentialRampToValueAtTime(.001,t+duration);gain.connect(ctx.destination);[1,2,3].forEach((harmonic,j)=>{const osc=ctx.createOscillator(),level=ctx.createGain();osc.type='sine';osc.frequency.value=440*2**((m-69)/12)*harmonic;level.gain.value=[1,.25,.08][j];osc.connect(level);level.connect(gain);osc.start(t);osc.stop(t+duration+.05)});const key=$(`[data-midi="${m}"]`);if(key){setTimeout(()=>key.classList.add('sounding'),i*spacing*1000);setTimeout(()=>key.classList.remove('sounding'),i*spacing*1000+450)}});$('#audioStatus').textContent='正在聆听 · '+notes.length+' 个音 · 合成键盘音色';}catch(e){$('#audioStatus').textContent='当前浏览器无法开启声音，请检查设备音频或换用现代浏览器。'}}
$('#root').addEventListener('change',e=>{rootIndex=+e.target.value;render()});$('#chordTypes').addEventListener('click',e=>{const b=e.target.closest('button');if(b){selected=chords.find(c=>c.id===b.dataset.chord);render();sound(currentNotes())}});$('#play').onclick=()=>sound(currentNotes());$('#arpeggio').onclick=()=>sound(currentNotes(),.32);$('#keyboard').onclick=e=>{const k=e.target.closest('[data-midi]');if(k)sound([+k.dataset.midi])};
function table(){const query=$('#search').value.toLowerCase().trim();const found=chords.filter(c=>(filter==='all'||c.group===filter)&&`${c.name} c${c.suffix} ${c.formula} ${c.intervals.join(' ')}`.toLowerCase().includes(query));$('#chordTable').innerHTML=found.length?found.map(c=>`<tr><td>${c.name}</td><td>C${c.suffix}</td><td>${c.formula}</td><td>${c.intervals.join(' · ')}</td><td><button data-explore="${c.id}">去实验 ↗</button></td></tr>`).join(''):'<tr><td colspan="5">没有找到匹配的和弦。试试“大七”或“m7”。</td></tr>';$('#tableCount').textContent=`共 ${found.length} 种和弦 · 公式相对根音表示；示例统一使用 C 根音。`}
$('#search').oninput=table;$('#filters').onclick=e=>{const b=e.target.closest('button');if(b){filter=b.dataset.filter;$$('#filters button').forEach(x=>x.classList.toggle('active',x===b));table()}};$('#chordTable').onclick=e=>{const b=e.target.closest('[data-explore]');if(b){selected=chords.find(c=>c.id===b.dataset.explore);rootIndex=0;$('#root').value=0;render();$('#lab').scrollIntoView({behavior:'smooth'});}};
const lessons=[['01','音与音程','声音之间的距离','音程既要数音名字母的跨度，也要看半音距离。C–E 是大三度（4 半音），C–E♭ 是小三度（3 半音）。'],['02','音阶与调性','音的共同语言','大调的相邻音距离是：全、全、半、全、全、全、半。C 大调由 C、D、E、F、G、A、B 构成。'],['03','和弦的构成','把音叠成色彩','在 C 大调中隔一个音叠一个音：C–E–G 得到大三和弦，D–F–A 得到小三和弦。调内三和弦的性质因此不同。'],['04','功能与进行','让声音有方向','在大调常见功能和声中，主功能带来安定，下属功能铺垫，属功能积累回归的张力。这些是语境中的倾向。'],['05','听见与应用','从理解到自己的音乐','先听根音的移动，再辨别和弦性质。用下方 ii–V–I 对照琴键与声音，把名称、构成和听感连接起来。']];
$('#path').innerHTML=lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===0?'active':''}" aria-pressed="${i===0}"><small>${l[0]}</small><b>↗</b><strong>${l[1]}</strong><span>${l[2]}</span></button>`).join('');function lesson(i){$('#lessonNote').textContent=lessons[i][3];$$('[data-lesson]').forEach(b=>{b.classList.toggle('active',+b.dataset.lesson===i);b.setAttribute('aria-pressed',+b.dataset.lesson===i)})}$('#path').onclick=e=>{const b=e.target.closest('[data-lesson]');if(b)lesson(+b.dataset.lesson)};
$('#playProgression').onclick=async()=>{if(progressionBusy)return;progressionBusy=true;const b=$('#playProgression');b.textContent='♫ 正在走向归途…';b.disabled=true;try{const sequence=[[62,65,69,72],[55,59,62,65],[60,64,67,71]];for(let i=0;i<3;i++){ $$('[data-step]').forEach(x=>x.classList.toggle('playing',+x.dataset.step===i));await sound(sequence[i],0,1.9);await new Promise(r=>setTimeout(r,1650))}}finally{$$('[data-step]').forEach(x=>x.classList.remove('playing'));b.textContent='▶ 再听一段归途';b.disabled=false;progressionBusy=false}};
const themes={garden:'晴日花园',monet:'莫奈池塘',mist:'雾中微光'};function theme(t){if(!themes[t])t='garden';document.body.dataset.theme=t;$('#themeButton span').textContent=themes[t];try{localStorage.setItem('harmony-theme',t)}catch{}$('meta[name="theme-color"]').content=getComputedStyle(document.body).getPropertyValue('--bg').trim();}let stored='garden';try{stored=localStorage.getItem('harmony-theme')||'garden'}catch{}theme(stored);$('#themeButton').onclick=()=>{const menu=$('#themeMenu');menu.hidden=!menu.hidden;$('#themeButton').setAttribute('aria-expanded',!menu.hidden)};$('#themeMenu').onclick=e=>{const b=e.target.closest('[data-theme]');if(b){theme(b.dataset.theme);$('#themeMenu').hidden=true;$('#themeButton').setAttribute('aria-expanded','false')}};document.addEventListener('click',e=>{if(!e.target.closest('#themeMenu')&&!e.target.closest('#themeButton')){$('#themeMenu').hidden=true;$('#themeButton').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#themeMenu').hidden=true;$('#themeButton').setAttribute('aria-expanded','false')}});render();table();lesson(0);
